def shortest_unique_prefixes(words: list[str]) -> list[str]:
    """
    For each word in `words`, return the shortest prefix that is not a prefix of any other word.
    If the word itself is a prefix of another word, return the whole word.
    """
    # Build a trie where each node stores the number of words that pass through it.
    class Node:
        __slots__ = ("count", "children")
        def __init__(self):
            self.count = 0
            self.children = {}

    root = Node()

    # Insert all words into the trie, incrementing counts along the path.
    for w in words:
        node = root
        for ch in w:
            node = node.children.setdefault(ch, Node())
            node.count += 1

    # For each word, find the shortest prefix where node.count == 1.
    result = []
    for w in words:
        node = root
        prefix = []
        unique_found = False
        for ch in w:
            node = node.children[ch]
            prefix.append(ch)
            if node.count == 1:
                unique_found = True
                break
        if unique_found:
            result.append("".join(prefix))
        else:
            # No unique prefix; the word itself is a prefix of another word.
            result.append(w)

    return result

